1 | // CORE — agent motion and population rendering (Phase 8).
2 | // Every registered profile is discoverable. Phase 9: agents stay at their virtual post unless a source gives them a
3 | // reason to move — no random wandering. Motion sources, always labelled:
4 | //   • recorded activity — trips driven by recorded autonomous missions (src/civ-activity.js): to the cited evidence
5 | //     location and back, on the validated pedestrian network (OSM walkways that cross no building footprint);
6 | //   • replay — positions driven by agents-world.js from a recorded mission log;
7 | //   • live — on the founder's machine only, agents of tasks the local supervisor is actually running
8 | //     (.core-local/live.json, never fetched on the public site).
9 | // Rendering by zoom: < 13.5 zone aggregates; 13.5–15.8 WebGL figures; ≥ 15.8 articulated DOM avatars for agents
10 | // in view (capped). The loop pauses when the tab is hidden; reduced motion freezes positions.
11 | (function () {
12 |   'use strict';
13 |   const G = globalThis, POP = () => G.CORE_POPULATION;

1 | // Constitution V1: local workflow permissions are never real-world authorization.
2 | export const AUTHORITY = Object.freeze({ constitution: '1.0', externalActionsEnabled: false, authenticatedApprovalSystem: false, reviewerLabelsAreIdentity: false });
3 | const LOCAL = new Set(['research', 'simulate', 'propose', 'critique', 'revise', 'record-review', 'stop', 'resume', 'export-local']);
4 | export function authorityGate(action) {
5 |   const allowed = LOCAL.has(action);
6 |   return { allowed, authorizesRealWorld: false, risk: allowed ? 'LOCAL_BOUNDED' : 'EXTERNAL_OR_UNKNOWN', reason: allowed ? 'Local workflow only; existing permissions, STOP and evidence gates still apply.' : 'BLOCKED: no authenticated approval system or external execution adapter.' };
7 | }
8 | const ROUTES = Object.freeze({ '/api/start': 'research', '/api/decision': 'propose', '/api/world': 'research', '/api/discover': 'research', '/api/decide': 'record-review', '/api/stop': 'stop', '/api/resume': 'resume', '/api/export': 'export-local' });

