3 | const fs = require('node:fs');
4 | const vm = require('node:vm');
5 | 
6 | test('committed corridor matches source assembly exactly', () => {
7 |   const expected = require('../scripts/lib/corridor-build.cjs').assemble(fs.readFileSync('src/template.html', 'utf8'), fs.readFileSync('src/engine.js', 'utf8'), fs.readFileSync('src/app.js', 'utf8'));
8 |   assert.equal(fs.readFileSync('corridor.html', 'utf8'), expected);
9 | });
10 | 
11 | test('inline scripts in both pages parse as JavaScript', () => {
12 |   for (const file of ['index.html', 'corridor.html']) {
13 |     const html = fs.readFileSync(file, 'utf8');
14 |     for (const script of html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/g)) {
15 |       new vm.Script(script[1], { filename: file });
16 |     }
17 |   }
18 | });

